51	/**
52	 * Global Exception handler for REST controllers.
53	 * <p>
54	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
55	 *
56	 * @author Vitaliy Fedoriv
57	 * @author Alexander Dudkin
58	 */
59	@ControllerAdvice
60	public class ExceptionControllerAdvice {
61	
62	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
63	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
64	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
65	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
66	
67	    private final OwnerFieldsValidator ownerFieldsValidator;
68	
69	    public ExceptionControllerAdvice(OwnerFieldsValidator ownerFieldsValidator) {
70	        this.ownerFieldsValidator = ownerFieldsValidator;
71	    }
72	
73	    /**
74	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
75	     * class.
76	     *
77	     * @param e     Object referring to the thrown exception.
78	     * @param status HTTP response status.
79	     * @param url URL request.
80	     */
81	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
82	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
83	        problemDetail.setType(URI.create(url.toString()));
84	        problemDetail.setTitle(e.getClass().getSimpleName());
85	        problemDetail.setDetail(detail);
86	        problemDetail.setProperty("timestamp", Instant.now());
87	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
88	        return problemDetail;
89	    }
90	
91	    /**
92	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
93	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
94	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
95	     * would catch it and report an authorization failure as a 500.
96	     *
97	     * @param e The {@link AccessDeniedException} to propagate
98	     * @throws AccessDeniedException always
99	     */
100	    @ExceptionHandler(AccessDeniedException.class)
101	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
102	        throw e;
103	    }
104	
105	    /**
106	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
107	     *
108	     * @param e The {@link Exception} to be handled
109	     * @param request {@link HttpServletRequest} object referring to the current request.
110	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
111	     */
112	    @ExceptionHandler(Exception.class)
113	    @ResponseBody
114	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
115	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
116	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
117	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
118	        return ResponseEntity.status(status).body(detail);
119	    }
120	
121	    /**
122	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
123	     * method returns a 404 Not Found status if an entity does not exist.
124	     *
125	     * @param e The {@link DataIntegrityViolationException} to be handled
126	     * @param request {@link HttpServletRequest} object referring to the current request.
127	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
128	     */
129	    @ExceptionHandler(DataIntegrityViolationException.class)
130	    @ResponseBody
131	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
132	        logger.warn("Data integrity violation at {} {}: {}",
133	            request.getMethod(),
134	            request.getRequestURI(),
135	            e.getMessage());
136	        logger.debug("Data integrity violation stacktrace", e);
137	        HttpStatus status = HttpStatus.NOT_FOUND;
138	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
139	        return ResponseEntity.status(status).body(detail);
140	    }
141	
142	    /**
143	     * Handles exception thrown by Bean Validation on controller methods parameters
144	     *
145	     * @param e The {@link MethodArgumentNotValidException} to be handled
146	     * @param request {@link HttpServletRequest} object referring to the current request.
147	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
148	     */
149	    @ExceptionHandler(MethodArgumentNotValidException.class)
150	    @ResponseBody
151	    public ResponseEntity<?> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
152	        HttpStatus status = HttpStatus.BAD_REQUEST;
153	        BindingErrorsResponse errors = new BindingErrorsResponse();
154	        BindingResult bindingResult = e.getBindingResult();
155	        if (bindingResult.getTarget() instanceof OwnerFieldsDto ownerFields) {
156	            List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFields);
157	            if (!missingFields.isEmpty()) {
158	                return ResponseEntity.status(status).body(new ValidationErrorsResponse(missingFields));
159	            }
160	        }
161	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
162	        if (bindingResult.hasErrors()) {
163	            errors.addAllErrors(bindingResult);
164	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
165	                .map(fieldError -> {
166	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
167	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
168	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
169	                        fieldError.getField(),
170	                        defaultMessage,
171	                        rejectedValue);
172	                    return new ValidationMessageDto(message)
173	                        .putAdditionalProperty("field", fieldError.getField())
174	                        .putAdditionalProperty("rejectedValue", rejectedValue)
175	                        .putAdditionalProperty("defaultMessage", defaultMessage);
176	                })
177	                .toList();
178	            logger.debug("Validation error at {} {}: {}",
179	                request.getMethod(),
180	                request.getRequestURI(),
181	                bindingResult.getFieldErrors());
182	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
183	            return ResponseEntity.status(status).body(detail);
184	        }
185	        return ResponseEntity.status(status).body(detail);
186	    }
187	
188	    /**
189	     * Handles {@link MissingOwnerFieldsException} raised when an owner is created with required
190	     * fields that are missing or blank. Returns a 400 Bad Request whose {@code errors} array lists
191	     * the name of each offending field.
192	     *
193	     * @param e The {@link MissingOwnerFieldsException} to be handled
194	     * @return A {@link ResponseEntity} containing the offending field names and a 400 Bad Request status.
195	     */
196	    @ExceptionHandler(MissingOwnerFieldsException.class)
197	    @ResponseBody
198	    public ResponseEntity<ValidationErrorsResponse> handleMissingOwnerFieldsException(MissingOwnerFieldsException e) {
199	        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(new ValidationErrorsResponse(e.getFields()));
200	    }
