225	     */
226	    @ExceptionHandler(InvalidEmailException.class)
227	    @ResponseBody
228	    public ResponseEntity<ValidationErrorsResponse> handleInvalidEmailException(InvalidEmailException e) {
229	        logger.debug("Invalid email: {}", e.getMessage());
230	        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
231	            .body(new ValidationErrorsResponse(List.of(InvalidEmailException.FIELD)));
