234	    /**
235	     * Handles {@link DuplicateTelephoneException} raised when an owner is created with a
236	     * normalized telephone that is already used by another owner. Returns a 409 Conflict
237	     * whose {@code errors} array names the offending field.
238	     *
239	     * @param e The {@link DuplicateTelephoneException} to be handled
240	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
241	     */
242	    @ExceptionHandler(DuplicateTelephoneException.class)
