250	    /**
251	     * Handles {@link DuplicateEmailException} raised when an owner is created with an email
252	     * whose lower-cased form is already used by another owner. Returns a 409 Conflict whose
253	     * {@code errors} array names the offending field.
254	     *
255	     * @param e The {@link DuplicateEmailException} to be handled
256	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
257	     */
258	    @ExceptionHandler(DuplicateEmailException.class)
259	    @ResponseBody
260	    public ResponseEntity<ValidationErrorsResponse> handleDuplicateEmailException(DuplicateEmailException e) {
261	        logger.debug("Duplicate email: {}", e.getMessage());
