266	    /**
267	     * Handles {@link DuplicateHouseholdException} raised when an owner is created whose last
268	     * name and address already belong to another owner and the request did not opt in via
269	     * {@code sharesHousehold}. Returns a 409 Conflict whose {@code errors} array names the
270	     * offending fields.
271	     *
272	     * @param e The {@link DuplicateHouseholdException} to be handled
273	     * @return A {@link ResponseEntity} containing the offending field names and a 409 Conflict status.
274	     */
275	    @ExceptionHandler(DuplicateHouseholdException.class)
276	    @ResponseBody
277	    public ResponseEntity<ValidationErrorsResponse> handleDuplicateHouseholdException(DuplicateHouseholdException e) {
278	        logger.debug("Duplicate household: {}", e.getMessage());
279	        return ResponseEntity.status(HttpStatus.CONFLICT)
280	            .body(new ValidationErrorsResponse(DuplicateHouseholdException.FIELDS));
281	    }
282	
283	    /**
284	     * Handles {@link CityOwnerLimitException} raised when an owner is created in a city that
285	     * already contains the maximum allowed number of owners. Returns a 409 Conflict whose
286	     * {@code errors} array names the offending field.
287	     *
288	     * @param e The {@link CityOwnerLimitException} to be handled
289	     * @return A {@link ResponseEntity} containing the offending field name and a 409 Conflict status.
290	     */
291	    @ExceptionHandler(CityOwnerLimitException.class)
292	    @ResponseBody
293	    public ResponseEntity<ValidationErrorsResponse> handleCityOwnerLimitException(CityOwnerLimitException e) {
294	        logger.debug("City owner limit reached: {}", e.getMessage());
295	        return ResponseEntity.status(HttpStatus.CONFLICT)
296	            .body(new ValidationErrorsResponse(List.of(CityOwnerLimitException.FIELD)));
297	    }
298	
299	    /**
300	     * Handles {@link DailyOwnerLimitException} raised when an owner is created on a day that has
301	     * already reached the maximum allowed number of owner registrations. Returns a 429 Too Many
302	     * Requests whose {@code errors} array names the offending field.
303	     *
304	     * @param e The {@link DailyOwnerLimitException} to be handled
305	     * @return A {@link ResponseEntity} containing the offending field name and a 429 status.
306	     */
307	    @ExceptionHandler(DailyOwnerLimitException.class)
308	    @ResponseBody
309	    public ResponseEntity<ValidationErrorsResponse> handleDailyOwnerLimitException(DailyOwnerLimitException e) {
310	        logger.debug("Daily owner limit reached: {}", e.getMessage());
311	        return ResponseEntity.status(HttpStatus.TOO_MANY_REQUESTS)
312	            .body(new ValidationErrorsResponse(List.of(DailyOwnerLimitException.FIELD)));
313	    }
