157	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
158	    @Override
159	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
160	        if (ownerFieldsDto != null) {
161	            ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
162	        }
163	        List<String> missingFields = ownerFieldsValidator.findMissingOrBlankFields(ownerFieldsDto);
164	        if (!missingFields.isEmpty()) {
165	            throw new MissingOwnerFieldsException(missingFields);
166	        }
167	        HttpHeaders headers = new HttpHeaders();
168	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
169	        Collection<Owner> sameLastName =
170	            this.clinicService.findOwnersByLastNameIgnoreCase(owner.getLastName());
171	        owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
172	        applyHouseholdPolicy(owner, ownerFieldsDto, sameLastName);
173	        String normalizedTelephone = telephoneNormalizer.normalize(owner.getTelephone());
174	        if (!this.clinicService.findOwnersByTelephone(normalizedTelephone).isEmpty()) {
175	            throw new DuplicateTelephoneException(normalizedTelephone);
176	        }
177	        owner.setTelephone(normalizedTelephone);
178	        String normalizedEmail = emailNormalizer.normalize(owner.getEmail());
179	        if (normalizedEmail != null && !this.clinicService.findOwnersByEmailIgnoreCase(normalizedEmail).isEmpty()) {
180	            throw new DuplicateEmailException(normalizedEmail);
181	        }
182	        owner.setEmail(normalizedEmail);
183	        if (owner.getRegistrationDate() == null) {
184	            owner.setRegistrationDate(LocalDate.now());
185	        }
186	        owner.setRegistrationDate(BusinessDayResolver.toBusinessDay(owner.getRegistrationDate()));
187	        LocalDate registrationDate = owner.getRegistrationDate();
188	        long ownersRegisteredToday = clinicService.countOwnersByRegistrationDate(registrationDate);
189	        if (ownersRegisteredToday >= DailyOwnerLimitException.MAX_OWNERS_PER_DAY) {
190	            throw new DailyOwnerLimitException(registrationDate);
191	        }
192	        owner.setBulkSignupWarning(bulkSignupWarningEvaluator.isBulkSignup(ownersRegisteredToday));
193	        long cityOwnerCount = clinicService.countOwnersByCity(owner.getCity());
194	        if (cityOwnerCount >= CityOwnerLimitException.MAX_OWNERS_PER_CITY) {
195	            throw new CityOwnerLimitException(owner.getCity());
196	        }
197	        owner.setCustomerCode(customerCodeGenerator.generate(
198	            owner.getCity(), owner.getLastName(), cityOwnerCount));
199	        this.clinicService.saveOwner(owner);
200	        ownerAuditLogger.ownerCreated(owner);
201	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
202	        headers.setLocation(UriComponentsBuilder.newInstance()
203	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
204	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
205	    }
