207	    /**
208	     * Applies the household rule to an owner about to be created. When the owner shares a
209	     * household (same last name and address, compared case-insensitively with collapsed
210	     * whitespace) with an existing owner, creation is rejected unless the request opted in via
211	     * {@code sharesHousehold}. When it opts in, the new owner and every existing household
212	     * member are stamped with the same stable {@code householdId}.
213	     *
214	     * <p>The new owner's household size after this create is recorded on it (the existing members
215	     * plus the owner itself), so an owner joining a household of three or more can be recognised.
216	     *
217	     * @throws DuplicateHouseholdException if a conflicting owner exists and the caller did not opt in
218	     */
219	    private void applyHouseholdPolicy(Owner owner, OwnerFieldsDto ownerFieldsDto, Collection<Owner> sameLastName) {
220	        List<Owner> members = householdDuplicateValidator.findHouseholdMembers(owner, sameLastName);
221	        owner.setHouseholdSize(members.size() + 1);
222	        if (members.isEmpty()) {
223	            return;
224	        }
225	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
226	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
227	        }
228	        String householdId = householdIdGenerator.generate(owner);
229	        owner.setHouseholdId(householdId);
230	        for (Owner member : members) {
231	            if (!householdId.equals(member.getHouseholdId())) {
232	                member.setHouseholdId(householdId);
233	                this.clinicService.saveOwner(member);
234	            }
235	        }
236	    }
